function PortalGateway() { return <div className="portal-gateway"><div className="gateway-card"><div className="brand-lockup gateway-brand"><img src="/arbitrade-mark.svg" alt="Arbitrade"/><div><strong>arbitrade</strong><span>secure customer and operations portal</span></div></div><div className="gateway-kicker"><span className="pulse"/> SECURE PRODUCTION CONFIGURATION</div><h1>Choose a secure workspace</h1><p>Separate customer and operations workspaces. Customers can register or sign in with an Arbitrade email and password.</p><div className="gateway-portals"><button className="portal-choice customer-choice" onClick={()=>{window.location.href="/customer"}}><div className="portal-choice-icon"><WalletCards size={22}/></div><div><strong>Customer portal</strong><span>Register or sign in</span><small>Wallets · live opportunities · notifications · allocations</small></div><ChevronRight size={18}/></button><button className="portal-choice admin-choice" onClick={()=>{window.location.href="/ops-console-7f3a"}}><div className="portal-choice-icon"><ShieldCheck size={22}/></div><div><strong>Admin portal</strong><span>Administrator access</span><small>Policies · packages · customer controls · API health</small></div><ChevronRight size={18}/></button></div><div className="gateway-foot"><ShieldCheck size={14}/> Provider connections are disabled until configured, verified and approved by an administrator.</div></div></div>; }
function CustomerBalanceRibbon({push,packageName,maxPopupsPerMinute}:{push:(message:string)=>void;packageName?:string;maxPopupsPerMinute?:number}) { const q=trpc.customer.balances.useQuery(undefined,{refetchInterval:5000}); const [expanded,setExpanded]=useState<string|null>(null); const rows=q.data?.balances||[]; const currencies=q.data?.currencies||[]; const meta=(code:string)=>currencies.find((x:any)=>x.code===code); const format=(minor:number,code:string)=>{const c=meta(code);const scale=c?.scale??2;return `${c?.symbol||code}${(minor/Math.pow(10,scale)).toLocaleString(undefined,{minimumFractionDigits:Math.min(scale,2),maximumFractionDigits:scale})}`}; return <section className="customer-balance-ribbon"><div className="customer-balance-ribbon-head"><div className="customer-balance-package"><Sparkles size={21}/><span><strong>{packageName||"Customer"} package</strong><small>{maxPopupsPerMinute||0} opportunities / min</small></span></div></div><div className="customer-balance-cards">{q.isLoading?[1,2,3].map(x=><div className="customer-balance-card loading" key={x}>Loading wallet…</div>):rows.map(row=>{const c=meta(row.currency);const open=expanded===row.currency;return <div className={`customer-balance-card ${open?'open':''}`} key={row.currency}><button className="customer-balance-trigger" onClick={()=>setExpanded(open?null:row.currency)}><span className="customer-balance-icon">{c?.symbol||row.currency[0]}</span><span className="customer-balance-name"><strong>{c?.name||row.currency}</strong><small>{row.currency} · Available</small></span><b>{format(row.availableMinor,row.currency)}</b><ChevronDown size={15} className={open?'rotated':''}/></button>{open&&<div className="customer-balance-actions"><button onClick={()=>push(`Deposit ${c?.name||row.currency}: provider flow opened`)}><ArrowDownToLine size={14}/><span><strong>Deposit</strong><small>Add funds to {row.currency}</small></span></button><button onClick={()=>push(`Withdrawal ${c?.name||row.currency}: provider and custody approval required`)}><ArrowUpRight size={14}/><span><strong>Withdraw</strong><small>Request payout from {row.currency}</small></span></button></div>}</div>})}</div><p className="customer-balance-note"><ShieldCheck size={13}/> Balances are live database-backed practice ledger values. Deposit and withdrawal requests require configured providers and approval.</p></section>; }
function PortalHeader({mode,user}:{mode:"customer"|"admin";user?:{name:string|null;email:string|null}}) { const branding=getBranding(); applyBranding(branding); const logout=trpc.auth.logout.useMutation({onSuccess:()=>{window.location.href=mode==="customer"?"/customer":"/"},onError:()=>{window.location.href=mode==="customer"?"/customer":"/"}}); return <header className="portal-header"><div className="brand-lockup"><img src={branding.logoUrl} alt={branding.platformName}/><div><strong>{branding.platformName}</strong><span>{mode === "customer" ? "customer workspace" : "operations control"}</span></div></div><div className="portal-session"><span className="test-account-dot"/> {mode === "customer" ? `${user?.name || user?.email || "Authenticated customer"}` : "Authenticated administrator"}<button onClick={()=>{window.location.href="/"}}>Switch portal</button><button className="secondary-button" disabled={logout.isPending} onClick={()=>logout.mutate()}>{logout.isPending?"Logging out…":"Log out"}</button></div></header>; }

function CustomerAuth({onAuthenticated}:{onAuthenticated:()=>void}) { const [mode,setMode]=useState<"signup"|"signin">("signup"); const [form,setForm]=useState({firstName:"",lastName:"",email:"",password:""}); const [error,setError]=useState(""); const [busy,setBusy]=useState(false); const update=(key:string,value:string)=>setForm(x=>({...x,[key]:value})); const submit=async()=>{setError("");setBusy(true);try{const url=mode==="signup"?"/api/customer/register":"/api/customer/login";const body=mode==="signup"?form:{email:form.email,password:form.password};const response=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.error||"Unable to continue");onAuthenticated()}catch(e){setError(e instanceof Error?e.message:"Unable to continue")}finally{setBusy(false)}};return <div className="auth-shell"><div className="auth-card"><div className="auth-logo"><img src="/arbitrade-mark.svg" alt="Arbitrade"/><span>arbitrade</span></div><div className="auth-kicker"><span className="pulse"/> Customer access</div><h1>{mode==="signup"?"Create your customer account":"Welcome back"}</h1><p className="auth-subtitle">Use your Arbitrade customer email and password. Authentication is handled by the production database and secure server session.</p><div className="auth-tabs"><button className={mode==="signup"?"active":""} onClick={()=>{setMode("signup");setError("")}}>Register</button><button className={mode==="signin"?"active":""} onClick={()=>{setMode("signin");setError("")}}>Sign in</button></div>{mode==="signup"&&<div className="auth-form-grid"><label><span>First name</span><input value={form.firstName} onChange={e=>update("firstName",e.target.value)} placeholder="Jordan"/></label><label><span>Last name</span><input value={form.lastName} onChange={e=>update("lastName",e.target.value)} placeholder="Davis"/></label></div>}<label className="auth-email-label"><span>Email address</span><div className="input-with-icon"><Mail size={14}/><input type="email" value={form.email} onChange={e=>update("email",e.target.value)} placeholder="you@example.com" autoComplete="email"/></div></label><label className="auth-email-label"><span>Password</span><div className="input-with-icon"><KeyRound size={14}/><input type="password" value={form.password} onChange={e=>update("password",e.target.value)} placeholder="At least 10 characters" autoComplete={mode==="signup"?"new-password":"current-password"}/></div></label>{error&&<div className="auth-error"><CircleHelp size={14}/>{error}</div>}<button className="auth-primary" disabled={busy} onClick={submit}>{busy?"Working…":mode==="signup"?"Register customer account":"Sign in to customer portal"} <ChevronRight size={16}/></button><div className="auth-feature-strip"><div><ShieldCheck size={14}/><span>Secure session</span></div><div><KeyRound size={14}/><span>Password protected</span></div><div><Bell size={14}/><span>Live alerts</span></div></div><div className="auth-demo-note">New accounts receive the administrator-configured promotional credit. It can support eligible allocations but cannot be withdrawn.</div></div></div>; }
